insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000001', 1, 1, 'Halo, tuts piano!', 'Kenalan dengan tuts hitam dan putih, cari Do di tengah piano, lalu main pakai lima jari kanan.', 2, 15, '["Cari semua C di piano tanpa melihat tulisan, lalu mainkan C sampai G pakai jari 1 sampai 5.","Mainkan Do-Re-Mi-Fa-Sol naik lalu turun lagi tanpa berhenti, di tempo 80 BPM."]'::jsonb, '{"title":"Lima jari kanan, C sampai G","notation":"C4/q, D4/q, E4/q, F4/q, G4/q, F4/q, E4/q, D4/q, C4/w","clef":"treble","bpm_start":60,"bpm_goal":80}'::jsonb)
