insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000101', '00000000-0000-4000-8000-000000000001', 1, 1, 'Tuts putih dan tuts hitam', 'text', 'Lihat tuts hitamnya: ada yang berdua, ada yang bertiga. Nada C (Do) selalu ada tepat di kiri dua tuts hitam. Coba tekan semua C di piano di bawah. C yang paling dekat dengan tengah piano namanya C4.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000102', '00000000-0000-4000-8000-000000000001', 2, 1, 'Do-Re-Mi-Fa-Sol', 'interactive_sheet', 'Taruh ibu jari kanan (jari 1) di C4. Setiap jari dapat satu tuts, sampai kelingking di G4. Sekarang mainkan satu per satu!', 'C4/q, D4/q, E4/q, F4/q, G4/w', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000103', '00000000-0000-4000-8000-000000000001', 3, 2, 'Mary Had a Little Lamb', 'interactive_sheet', 'Lagu pertamamu! Cukup tiga jari. Tekan Play untuk mendengarkan dulu, lalu ikuti di piano.', 'E4/q, D4/q, C4/q, D4/q, E4/q, E4/q, E4/h, D4/q, D4/q, D4/h, E4/q, G4/q, G4/h', 'treble', '4/4', null)
