insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000002', 2, 1, 'Dua tangan, sepuluh jari', 'Nomor jari, cara duduk yang enak, dan tangan kiri mulai ikut bermain di C3.', 2, 15, '["Mainkan C3 sampai G3 dengan tangan kiri. Kelingking (jari 5) mulai di C3.","Mainkan Twinkle Twinkle dengan tangan kanan, lalu coba bagian yang sama dengan tangan kiri, lebih rendah."]'::jsonb, '{"title":"Lima jari kiri, C sampai G","notation":"C3/q, D3/q, E3/q, F3/q, G3/q, F3/q, E3/q, D3/q, C3/w","clef":"bass","bpm_start":60,"bpm_goal":80}'::jsonb)
