insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000201', '00000000-0000-4000-8000-000000000002', 1, 1, 'Penomoran jari dan postur', 'text', 'Kedua tangan punya nomor yang sama: ibu jari 1, kelingking 5. Duduk tegak, siku sejajar tuts, dan bentuk jari melengkung seperti sedang memegang bola kecil. Coba tekan C3 dengan jari 5 kiri dan C4 dengan jari 1 kanan.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000202', '00000000-0000-4000-8000-000000000002', 2, 1, 'Tangan kiri: C sampai G', 'interactive_sheet', 'Partitur ini memakai Bass Clef, tanda untuk nada-nada rendah. Kelingking kiri mulai di C3.', 'C3/q, D3/q, E3/q, F3/q, G3/w', 'bass', '4/4', null)
