insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000203', '00000000-0000-4000-8000-000000000002', 3, 2, 'Twinkle Twinkle Little Star', 'interactive_sheet', 'Lagu bintang kecil! Klik setiap not untuk mendengarnya satu per satu, atau tekan Play untuk mendengar lagunya utuh.', 'C4/q, C4/q, G4/q, G4/q, A4/q, A4/q, G4/h, F4/q, F4/q, E4/q, E4/q, D4/q, D4/q, C4/h', 'treble', '4/4', null)
