insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000204', '00000000-0000-4000-8000-000000000002', 4, 2, 'Kuis: dua tangan', 'quiz', null, null, 'treble', '4/4', '[{"question":"Di posisi C tangan kiri, jari apa yang menekan C3?","choices":["Jari 1","Jari 3","Jari 5"],"answer_index":2},{"question":"Bentuk jari yang benar saat bermain piano…","choices":["Lurus dan kaku","Melengkung","Ditekuk ke belakang"],"answer_index":1}]'::jsonb)
