insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000003', 3, 2, 'Rumah not: paranada dan Treble Clef', 'Not punya rumah berupa lima garis. Kita belajar not yang duduk di garis dan di sela-selanya.', 3, 20, '["Hafalkan not di garis Treble Clef dari bawah: E G B D F.","Hafalkan not di spasi Treble Clef: F A C E, seperti kata FACE.","Baca dan mainkan delapan birama baru tanpa menuliskan nama notnya dulu."]'::jsonb, '{"title":"Lompatan terts, C sampai C","notation":"C4/q, E4/q, G4/q, E4/q, D4/q, F4/q, A4/q, F4/q, E4/q, G4/q, B4/q, G4/q, C5/w","clef":"treble","bpm_start":60,"bpm_goal":90}'::jsonb)
