insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000301', '00000000-0000-4000-8000-000000000003', 1, 1, 'Lima garis paranada', 'text', 'Not balok tinggal di lima garis yang namanya paranada (staff). Makin tinggi letak not, makin tinggi bunyinya. Tanda keriting di depan namanya Treble Clef (kunci G). Ekornya melingkari garis kedua dari bawah, dan garis itu adalah G4.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000302', '00000000-0000-4000-8000-000000000003', 2, 1, 'Not di garis: E G B D F', 'interactive_sheet', 'Kelima not ini semuanya duduk di atas garis. Mainkan sambil menyebut namanya keras-keras!', 'E4/q, G4/q, B4/q, D5/q, F5/w', 'treble', '4/4', null)
