insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000304', '00000000-0000-4000-8000-000000000003', 4, 3, 'Ode to Joy (sederhana)', 'interactive_sheet', 'Lagu ciptaan Beethoven ini cuma pakai lima nada, C sampai G. Coba baca notnya langsung dari paranada.', 'E4/q, E4/q, F4/q, G4/q, G4/q, F4/q, E4/q, D4/q, C4/q, C4/q, D4/q, E4/q, E4/q, D4/q, D4/h', 'treble', '4/4', null)
