insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000305', '00000000-0000-4000-8000-000000000003', 5, 3, 'Kuis: Treble Clef', 'quiz', null, null, 'treble', '4/4', '[{"question":"Not di garis Treble Clef, dari bawah ke atas, adalah…","choices":["E G B D F","F A C E","G B D F A"],"answer_index":0},{"question":"Nama lain Treble Clef adalah…","choices":["Kunci F","Kunci G","Kunci C"],"answer_index":1},{"question":"Not di sela paling bawah Treble Clef adalah…","choices":["E","F","A"],"answer_index":1}]'::jsonb)
