insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000401', '00000000-0000-4000-8000-000000000004', 1, 1, 'Bass Clef', 'text', 'Bass Clef (kunci F) dipakai untuk nada rendah, biasanya dimainkan tangan kiri. Lihat dua titiknya: keduanya mengapit garis keempat dari bawah, dan garis itu adalah F3.', null, 'treble', '4/4', null)
