insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000403', '00000000-0000-4000-8000-000000000004', 3, 2, 'Whole, half, dan quarter note', 'interactive_sheet', 'Whole note ditahan 4 ketukan, half note 2 ketukan, quarter note 1 ketukan. Tekan Play dan dengarkan mana yang panjang, mana yang pendek.', 'C4/w, E4/h, G4/h, C5/q, G4/q, E4/q, C4/q', 'treble', '4/4', null)
