insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000404', '00000000-0000-4000-8000-000000000004', 4, 3, 'When the Saints (tangan kiri)', 'interactive_sheet', 'Lagu terkenal ini dimainkan tangan kiri di Bass Clef. Setiap bagian mulai setelah satu ketukan diam (rest), lalu berhenti di whole note yang ditahan lama.', 'R/q, C3/q, E3/q, F3/q, G3/w, R/q, C3/q, E3/q, F3/q, G3/w, R/q, C3/q, E3/q, F3/q, G3/h, E3/h, C3/h, E3/h, D3/w', 'bass', '4/4', null)
