insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000005', 5, 2, 'Main ritme: rest, dotted, eighth note', 'Belajar diam yang tetap dihitung, not bertitik, dan eighth note yang cepat, dengan hitungan 1-dan-2-dan.', 3, 20, '["Hitung setiap rest keras-keras. Jangan dilewati, ya.","Mainkan dotted quarter lalu eighth note sambil menghitung 1-dan-2.","Mainkan Ode to Joy dengan ritme dotted di tempo 90 BPM."]'::jsonb, '{"title":"Eighth note dan rest","notation":"C4/8, D4/8, E4/8, F4/8, G4/q, R/q, G4/8, F4/8, E4/8, D4/8, C4/h","clef":"treble","bpm_start":60,"bpm_goal":96}'::jsonb)
