insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000504', '00000000-0000-4000-8000-000000000005', 4, 3, 'Kuis: ritme', 'quiz', null, null, 'treble', '4/4', '[{"question":"Berapa eighth note yang sama panjang dengan satu half note?","choices":["2","4","8"],"answer_index":1},{"question":"Titik di belakang not membuat not itu lebih panjang sebanyak…","choices":["Seperempat","Setengah","Dua kali lipat"],"answer_index":1},{"question":"Kalau bertemu rest, kamu harus…","choices":["Melewatinya","Diam sambil tetap menghitung","Menahan not sebelumnya"],"answer_index":1}]'::jsonb)
