insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000006', 6, 3, 'Tangga nada: scale C, G, F', 'Naik turun tangga nada (scale) dengan ibu jari yang menyeberang di bawah jari lain.', 4, 25, '["Mainkan scale C mayor dengan jari 1-2-3, ibu jari menyeberang, lalu 1-2-3-4-5.","Tambahkan scale G mayor. Ingat, nada ketujuhnya F# (tuts hitam).","Tambahkan scale F mayor dengan jari 1-2-3-4-1-2-3-4. Ingat, ada Bb (tuts hitam).","Mainkan ketiga scale berturut-turut di 96 BPM tanpa berhenti."]'::jsonb, '{"title":"Scale C mayor, eighth note","notation":"C4/8, D4/8, E4/8, F4/8, G4/8, A4/8, B4/8, C5/8, B4/8, A4/8, G4/8, F4/8, E4/8, D4/8, C4/q","clef":"treble","bpm_start":60,"bpm_goal":96}'::jsonb)
  on conflict (id) do update set level = excluded.level, tier = excluded.tier, title = excluded.title, description = excluded.description, duration_weeks = excluded.duration_weeks, daily_minutes = excluded.daily_minutes, weekly_targets = excluded.weekly_targets, drill = excluded.drill;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000601', '00000000-0000-4000-8000-000000000006', 1, 1, 'Pola whole-whole-half', 'text', 'Setiap scale mayor naik dengan pola langkah yang sama: besar, besar, kecil, besar, besar, besar, kecil. Langkah besar namanya whole step, langkah kecil namanya half step. Half step artinya pindah ke tuts sebelahnya persis, misalnya E ke F.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000602', '00000000-0000-4000-8000-000000000006', 2, 1, 'Scale C mayor', 'interactive_sheet', 'Setelah jari 3 menekan E, ibu jari menyelinap lewat bawah ke F. Coba pelan-pelan dulu.', 'C4/q, D4/q, E4/q, F4/q, G4/q, A4/q, B4/q, C5/q, B4/q, A4/q, G4/q, F4/q, E4/q, D4/q, C4/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000603', '00000000-0000-4000-8000-000000000006', 3, 2, 'Scale G mayor', 'interactive_sheet', 'Mirip C mayor, tapi nada ketujuhnya naik ke tuts hitam: F#.', 'G4/q, A4/q, B4/q, C5/q, D5/q, E5/q, F#5/q, G5/q, F#5/q, E5/q, D5/q, C5/q, B4/q, A4/q, G4/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000604', '00000000-0000-4000-8000-000000000006', 4, 3, 'Scale F mayor', 'interactive_sheet', 'Nada keempatnya turun ke tuts hitam: Bb. Kali ini ibu jari menyeberang setelah jari 4.', 'F4/q, G4/q, A4/q, Bb4/q, C5/q, D5/q, E5/q, F5/q, E5/q, D5/q, C5/q, Bb4/q, A4/q, G4/q, F4/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000605', '00000000-0000-4000-8000-000000000006', 5, 4, 'Kuis: scale mayor', 'quiz', null, null, 'treble', '4/4', '[{"question":"Pola langkah scale mayor adalah…","choices":["W-W-H-W-W-W-H","W-H-W-W-H-W-W","H-W-W-W-H-W-W"],"answer_index":0},{"question":"Tuts hitam di scale G mayor adalah…","choices":["C#","F#","G#"],"answer_index":1},{"question":"Tuts hitam di scale F mayor adalah…","choices":["Bb","Eb","Ab"],"answer_index":0}]'::jsonb)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000007', 7, 3, 'Chord: tiga nada sekaligus', 'Menekan tiga nada bersamaan (chord), berpindah antar-chord, lalu mengiringi lagu dengan dua tangan.', 4, 25, '["Bentuk chord C, F, dan G dengan jari 1-3-5 tanpa melihat tangan.","Pindah dari C ke F ke G lalu kembali ke C tanpa berhenti.","Tangan kiri menahan chord, tangan kanan memainkan melodi lima nada.","Iringi lagu Twinkle Twinkle dengan chord I, IV, dan V."]'::jsonb, '{"title":"Progresi I-IV-V-I","notation":"(C4 E4 G4)/h, (F4 A4 C5)/h, (G4 B4 D5)/h, (C4 E4 G4)/h","clef":"treble","bpm_start":60,"bpm_goal":90}'::jsonb)
  on conflict (id) do update set level = excluded.level, tier = excluded.tier, title = excluded.title, description = excluded.description, duration_weeks = excluded.duration_weeks, daily_minutes = excluded.daily_minutes, weekly_targets = excluded.weekly_targets, drill = excluded.drill;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000701', '00000000-0000-4000-8000-000000000007', 1, 1, 'Apa itu triad', 'text', 'Triad adalah chord yang terdiri dari tiga nada yang ditekan bersamaan. Caranya gampang: pilih satu tuts, lewati satu, tekan, lewati satu, tekan. Triad C mayor berisi C, E, dan G. Coba tekan ketiganya di piano di bawah.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000702', '00000000-0000-4000-8000-000000000007', 2, 1, 'Triad C, F, G', 'interactive_sheet', 'Dengan tiga chord ini saja, kamu sudah bisa mengiringi banyak sekali lagu.', '(C4 E4 G4)/w, (F4 A4 C5)/w, (G4 B4 D5)/w', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000703', '00000000-0000-4000-8000-000000000007', 3, 2, 'Progresi I-IV-V-I', 'interactive_sheet', 'Di C mayor, chord I adalah C, IV adalah F, dan V adalah G. Pindah chord tepat di ketukan pertama, ya.', '(C4 E4 G4)/q, (C4 E4 G4)/q, (F4 A4 C5)/q, (F4 A4 C5)/q, (G4 B4 D5)/q, (G4 B4 D5)/q, (C4 E4 G4)/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000704', '00000000-0000-4000-8000-000000000007', 4, 3, 'Chord tangan kiri', 'interactive_sheet', 'Sekarang tangan kiri yang main chord, lebih rendah. Susunan nada F dan G sedikit diubah supaya tangan tidak perlu melompat jauh.', '(C3 E3 G3)/w, (C3 F3 A3)/w, (B2 D3 G3)/w, (C3 E3 G3)/w', 'bass', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000705', '00000000-0000-4000-8000-000000000007', 5, 4, 'Kuis: chord', 'quiz', null, null, 'treble', '4/4', '[{"question":"Triad C mayor berisi nada…","choices":["C E G","C F A","C D E"],"answer_index":0},{"question":"Di C mayor, chord V adalah…","choices":["F","G","A"],"answer_index":1},{"question":"Jari yang dipakai untuk menekan triad dengan tangan kanan…","choices":["1-2-3","1-3-5","2-3-4"],"answer_index":1}]'::jsonb)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000008', 8, 3, 'Nada sedih: scale minor', 'Scale minor terdengar lebih sedih atau misterius. Kita juga belajar membaca key signature.', 4, 30, '["Mainkan A minor lalu C mayor. Mana yang terdengar ceria, mana yang sedih?","Mainkan A minor harmonic, dengan G# di nada ketujuh.","Kenali key signature satu kres (G mayor atau E minor) dan satu mol (F mayor atau D minor).","Mainkan scale E minor dan D minor harmonic tanpa melihat partitur."]'::jsonb, '{"title":"A minor natural, eighth note","notation":"A3/8, B3/8, C4/8, D4/8, E4/8, F4/8, G4/8, A4/8, G4/8, F4/8, E4/8, D4/8, C4/8, B3/8, A3/q","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
  on conflict (id) do update set level = excluded.level, tier = excluded.tier, title = excluded.title, description = excluded.description, duration_weeks = excluded.duration_weeks, daily_minutes = excluded.daily_minutes, weekly_targets = excluded.weekly_targets, drill = excluded.drill;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000801', '00000000-0000-4000-8000-000000000008', 1, 1, 'A minor natural', 'interactive_sheet', 'Semua tuts putih, tapi mulainya dari A. Dengarkan, rasanya lebih sedih dibanding C mayor. Scale ini disebut relatif minor dari C mayor.', 'A3/q, B3/q, C4/q, D4/q, E4/q, F4/q, G4/q, A4/q, G4/q, F4/q, E4/q, D4/q, C4/q, B3/q, A3/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000802', '00000000-0000-4000-8000-000000000008', 2, 2, 'A minor harmonic', 'interactive_sheet', 'Nada ketujuhnya naik ke tuts hitam: G#. Lompatan dari F ke G# membuat scale ini terdengar seperti musik petualangan.', 'A3/q, B3/q, C4/q, D4/q, E4/q, F4/q, G#4/q, A4/q, G#4/q, F4/q, E4/q, D4/q, C4/q, B3/q, A3/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000803', '00000000-0000-4000-8000-000000000008', 3, 3, 'Membaca key signature', 'text', 'Key signature adalah kres atau mol di awal paranada. Satu kres (F#) berarti G mayor atau E minor. Satu mol (Bb) berarti F mayor atau D minor. Untuk membedakannya, lihat nada terakhir: lagu dalam G mayor biasanya berakhir di G, lagu dalam E minor di E.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000804', '00000000-0000-4000-8000-000000000008', 4, 4, 'E minor harmonic', 'interactive_sheet', 'Ada satu kres dari key signature (F#), ditambah D# di nada ketujuh.', 'E4/q, F#4/q, G4/q, A4/q, B4/q, C5/q, D#5/q, E5/q, D#5/q, C5/q, B4/q, A4/q, G4/q, F#4/q, E4/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000805', '00000000-0000-4000-8000-000000000008', 5, 4, 'Kuis: minor', 'quiz', null, null, 'treble', '4/4', '[{"question":"Relatif minor dari C mayor adalah…","choices":["E minor","A minor","D minor"],"answer_index":1},{"question":"Di scale minor harmonic, nada keberapa yang dinaikkan?","choices":["Tiga","Lima","Tujuh"],"answer_index":2},{"question":"Key signature dengan satu mol (Bb) berarti lagunya di…","choices":["G mayor atau E minor","F mayor atau D minor","D mayor atau B minor"],"answer_index":1}]'::jsonb)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000009', 9, 4, 'Arpeggio: chord yang berjalan', 'Nada-nada chord dimainkan satu per satu naik turun, seperti menaiki tangga sambil melompat.', 4, 30, '["Mainkan arpeggio C mayor dua oktaf. Saat ibu jari menyeberang, bunyinya tetap halus.","Tambahkan arpeggio F dan G mayor.","Tambahkan arpeggio A minor dan E minor.","Mainkan kelima arpeggio di 108 BPM dengan eighth note."]'::jsonb, '{"title":"Arpeggio C dan F","notation":"C4/8, E4/8, G4/8, C5/8, G4/8, E4/8, C4/q, F4/8, A4/8, C5/8, F5/8, C5/8, A4/8, F4/q","clef":"treble","bpm_start":60,"bpm_goal":108}'::jsonb)
  on conflict (id) do update set level = excluded.level, tier = excluded.tier, title = excluded.title, description = excluded.description, duration_weeks = excluded.duration_weeks, daily_minutes = excluded.daily_minutes, weekly_targets = excluded.weekly_targets, drill = excluded.drill;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000901', '00000000-0000-4000-8000-000000000009', 1, 1, 'Arpeggio C mayor', 'interactive_sheet', 'Nada C, E, dan G dimainkan satu per satu, naik sampai dua oktaf lalu turun lagi. Ibu jari menyeberang setelah jari 3.', 'C4/8, E4/8, G4/8, C5/8, E5/8, G5/8, C6/q, G5/8, E5/8, C5/8, G4/8, E4/8, C4/8, R/q', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000902', '00000000-0000-4000-8000-000000000009', 2, 2, 'Arpeggio F dan G', 'interactive_sheet', 'Bentuk tangannya sama seperti arpeggio C, hanya tempat mulainya yang pindah.', 'F4/8, A4/8, C5/8, F5/8, C5/8, A4/8, F4/q, G4/8, B4/8, D5/8, G5/8, D5/8, B4/8, G4/q', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000903', '00000000-0000-4000-8000-000000000009', 3, 3, 'Arpeggio minor', 'interactive_sheet', 'A minor dan E minor. Nada tengahnya lebih rendah setengah langkah dibanding versi mayor, makanya terdengar lebih sedih.', 'A3/8, C4/8, E4/8, A4/8, E4/8, C4/8, A3/q, E4/8, G4/8, B4/8, E5/8, B4/8, G4/8, E4/q', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000904', '00000000-0000-4000-8000-000000000009', 4, 4, 'Kuis: arpeggio', 'quiz', null, null, 'treble', '4/4', '[{"question":"Arpeggio itu apa?","choices":["Chord yang dimainkan satu per satu","Scale yang dimainkan cepat","Dua tangan bergantian"],"answer_index":0},{"question":"Arpeggio A minor berisi nada…","choices":["A C# E","A C E","A D F"],"answer_index":1}]'::jsonb)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000010', 10, 4, 'Keras, lembut, cepat, lambat', 'Membuat musik bercerita: kadang lembut (piano), kadang keras (forte), kadang melambat. Lalu main lagu klasik pertamamu.', 4, 30, '["Mainkan satu bagian lagu dengan lembut (p), lalu dengan keras (f), tanpa mengubah tempo.","Mainkan scale C mayor makin keras saat naik (crescendo) dan makin lembut saat turun (diminuendo).","Di empat ketukan terakhir lagu, perlambat sedikit demi sedikit (ritardando).","Rekam dirimu memainkan Minuet in G, lalu dengarkan bersama keluarga."]'::jsonb, '{"title":"Für Elise, frase pembuka","notation":"E5/8, D#5/8, E5/8, D#5/8, E5/8, B4/8, D5/8, C5/8, A4/q","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
  on conflict (id) do update set level = excluded.level, tier = excluded.tier, title = excluded.title, description = excluded.description, duration_weeks = excluded.duration_weeks, daily_minutes = excluded.daily_minutes, weekly_targets = excluded.weekly_targets, drill = excluded.drill;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001001', '00000000-0000-4000-8000-000000000010', 1, 1, 'Simbol dinamika: pp sampai ff', 'text', 'Huruf-huruf kecil di partitur memberi tahu seberapa keras kamu bermain. pp (pianissimo) sangat lembut, p (piano) lembut, mp dan mf sedang, f (forte) keras, ff (fortissimo) sangat keras. Rahasianya: makin cepat jari menekan tuts, makin keras bunyinya.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001002', '00000000-0000-4000-8000-000000000010', 2, 2, 'Crescendo pada scale C', 'interactive_sheet', 'Mulai lembut (p) di C4, makin keras sampai (f) di C5, lalu turun lagi pelan-pelan jadi lembut.', 'C4/q, D4/q, E4/q, F4/q, G4/q, A4/q, B4/q, C5/q, B4/q, A4/q, G4/q, F4/q, E4/q, D4/q, C4/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001003', '00000000-0000-4000-8000-000000000010', 3, 3, 'Für Elise (pembuka)', 'interactive_sheet', 'Lagu terkenal dari Beethoven. Mainkan sangat lembut (pianissimo), dengan E dan D# bergantian seperti bisikan. Aslinya ditulis dalam birama 3/8; di sini dirapikan ke 4/4 supaya mudah dibaca.', 'E5/8, D#5/8, E5/8, D#5/8, E5/8, B4/8, D5/8, C5/8, A4/q, R/8, C4/8, E4/8, A4/8, B4/q, R/8, E4/8, G#4/8, B4/8, C5/q, R/q', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001004', '00000000-0000-4000-8000-000000000010', 4, 4, 'Minuet in G (pembuka)', 'interactive_sheet', 'Lagu dansa dari buku catatan Anna Magdalena Bach, dalam birama 3/4. Hitung 1-2-3, 1-2-3, seperti orang berdansa. Mainkan agak keras (mezzo forte).', 'D5/q, G4/8, A4/8, B4/8, C5/8, D5/q, G4/q, G4/q, E5/q, C5/8, D5/8, E5/8, F#5/8, G5/q, G4/q, G4/q', 'treble', '3/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001005', '00000000-0000-4000-8000-000000000010', 5, 4, 'Kuis: dinamika', 'quiz', null, null, 'treble', '4/4', '[{"question":"Huruf p di partitur artinya…","choices":["Lembut","Keras","Pelan (tempo)"],"answer_index":0},{"question":"Crescendo artinya…","choices":["Makin lambat","Makin keras","Makin lembut"],"answer_index":1},{"question":"Ritardando artinya…","choices":["Makin cepat","Makin lambat","Berhenti mendadak"],"answer_index":1}]'::jsonb)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000011', 11, 5, 'Sight-reading: baca langsung main', 'Melihat partitur baru lalu langsung memainkannya tanpa berhenti. Mata selalu satu birama di depan jari.', 6, 30, '["Setiap hari, baca dan mainkan empat birama baru. Kalau salah, jalan terus.","Latih mata melihat birama berikutnya saat jari masih memainkan birama sekarang.","Sight-reading di Bass Clef, empat birama sehari.","Sight-reading dengan eighth note dan rest.","Sight-reading dengan key signature satu kres.","Baca enam belas birama baru di 80 BPM, dengan salah kurang dari tiga not."]'::jsonb, '{"title":"Bacaan pendek dengan lompatan","notation":"G4/q, E4/8, F4/8, G4/q, C5/q, B4/q, A4/8, G4/8, F4/h, E4/q, D4/q, C4/w","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
  on conflict (id) do update set level = excluded.level, tier = excluded.tier, title = excluded.title, description = excluded.description, duration_weeks = excluded.duration_weeks, daily_minutes = excluded.daily_minutes, weekly_targets = excluded.weekly_targets, drill = excluded.drill;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001101', '00000000-0000-4000-8000-000000000011', 1, 1, 'Aturan sight-reading', 'text', 'Sebelum mulai, lihat dulu key signature, birama, dan nada paling rendah serta paling tinggi. Lalu mainkan pelan-pelan dan jangan berhenti. Satu not salah tidak apa-apa, asal hitungannya tetap jalan.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001102', '00000000-0000-4000-8000-000000000011', 2, 2, 'Bacaan 1: melangkah', 'interactive_sheet', 'Mainkan sekali dari awal sampai akhir tanpa berhenti. Setelah itu, tekan Play untuk mengecek.', 'E4/q, F4/q, G4/q, E4/q, D4/q, E4/q, F4/h, G4/q, A4/q, B4/q, G4/q, C5/w', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001103', '00000000-0000-4000-8000-000000000011', 3, 3, 'Bacaan 2: Bass Clef', 'interactive_sheet', 'Sama seperti tadi, tapi kali ini dengan tangan kiri.', 'C3/q, D3/q, E3/q, C3/q, G3/h, F3/h, E3/q, D3/q, C3/q, B2/q, C3/w', 'bass', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001104', '00000000-0000-4000-8000-000000000011', 4, 4, 'Bacaan 3: ritme', 'interactive_sheet', 'Hati-hati dengan rest dan eighth note. Hitung pelan-pelan dulu sebelum mulai.', 'C5/8, B4/8, A4/q, R/q, G4/q, F4/8, G4/8, A4/q, R/8, A4/8, G4/q, E4/qd, D4/8, C4/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001105', '00000000-0000-4000-8000-000000000011', 5, 5, 'Bacaan 4: G mayor', 'interactive_sheet', 'Ada satu kres di depan, jadi setiap F dimainkan sebagai F# (tuts hitam).', 'G4/q, B4/q, D5/q, B4/q, A4/q, F#4/q, G4/h, D4/q, E4/q, F#4/q, A4/q, G4/w', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001106', '00000000-0000-4000-8000-000000000011', 6, 6, 'Kuis: sight-reading', 'quiz', null, null, 'treble', '4/4', '[{"question":"Saat sight-reading lalu kamu salah not, sebaiknya…","choices":["Berhenti dan ulangi","Terus jalan","Mulai dari awal"],"answer_index":1},{"question":"Apa yang dilihat dulu sebelum mulai membaca?","choices":["Judul saja","Key signature dan birama","Nomor halaman"],"answer_index":1}]'::jsonb)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000012', 12, 5, 'Konser kecil: klasik dan jazz', 'Chord seventh yang terdengar keren, lagu Bach yang indah, blues scale dengan rasa swing, lalu konser kecilmu sendiri.', 6, 30, '["Kenali tiga chord seventh: Dm7, G7, dan Cmaj7.","Mainkan ii-V-I di C mayor tanpa melihat tangan.","Mainkan delapan birama pertama Prelude in C dari Bach.","Mainkan blues scale C dengan rasa swing.","Dalam satu kali latihan, mainkan satu lagu klasik dan satu lagu jazz.","Adakan konser kecil di rumah: mainkan dua lagu tanpa berhenti di depan keluarga, lalu rekam."]'::jsonb, '{"title":"Progresi ii-V-I","notation":"(D4 F4 A4 C5)/w, (D4 F4 G4 B4)/w, (C4 E4 G4 B4)/w","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
  on conflict (id) do update set level = excluded.level, tier = excluded.tier, title = excluded.title, description = excluded.description, duration_weeks = excluded.duration_weeks, daily_minutes = excluded.daily_minutes, weekly_targets = excluded.weekly_targets, drill = excluded.drill;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001201', '00000000-0000-4000-8000-000000000012', 1, 1, 'Chord seventh', 'interactive_sheet', 'Chord seventh adalah triad yang ditambah satu nada lagi di atasnya, jadi empat nada. Dm7, G7, dan Cmaj7 sering dipakai di lagu jazz.', '(D4 F4 A4 C5)/w, (G4 B4 D5 F5)/w, (C4 E4 G4 B4)/w', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001202', '00000000-0000-4000-8000-000000000012', 2, 2, 'ii-V-I di C', 'interactive_sheet', 'Susunan nada G7 diubah sedikit (inversi) supaya jarimu hampir tidak perlu pindah dari Dm7.', '(D4 F4 A4 C5)/h, (D4 F4 G4 B4)/h, (C4 E4 G4 B4)/w', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001203', '00000000-0000-4000-8000-000000000012', 3, 3, 'Prelude in C, BWV 846 (pembuka)', 'interactive_sheet', 'Bach membuat lagu ini dari chord yang nadanya dimainkan satu per satu. Jaga semua sixteenth note tetap rata, seperti air yang mengalir.', 'C4/16, E4/16, G4/16, C5/16, E5/16, G4/16, C5/16, E5/16, C4/16, E4/16, G4/16, C5/16, E5/16, G4/16, C5/16, E5/16, C4/16, D4/16, A4/16, D5/16, F5/16, A4/16, D5/16, F5/16, C4/16, D4/16, A4/16, D5/16, F5/16, A4/16, D5/16, F5/16', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001204', '00000000-0000-4000-8000-000000000012', 4, 4, 'Blues scale C', 'interactive_sheet', 'Nadanya C, Eb, F, F#, G, Bb. Mainkan dengan rasa swing: dari setiap pasangan eighth note, yang pertama sedikit lebih panjang, seperti langkah sambil bergoyang.', 'C4/8, Eb4/8, F4/8, F#4/8, G4/8, Bb4/8, C5/q, Bb4/8, G4/8, F#4/8, F4/8, Eb4/8, C4/8, C4/q', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001205', '00000000-0000-4000-8000-000000000012', 5, 6, 'Kuis: repertoar', 'quiz', null, null, 'treble', '4/4', '[{"question":"Di C mayor, ii-V-I adalah…","choices":["Dm7 - G7 - Cmaj7","C - F - G","Am - Dm - G"],"answer_index":0},{"question":"Nada khas yang membuat blues scale terdengar blues adalah…","choices":["F#","B","D"],"answer_index":0},{"question":"Prelude in C dari Bach dibuat dari…","choices":["Melodi panjang","Chord yang dipecah","Scale cepat"],"answer_index":1}]'::jsonb)
